import axios from "axios";

type STAGE = "prod" | "dev";

export const getApiKey = async (stage: STAGE, accessToken: string, project: string) => {
    try {
        const { data } = await axios.post(`https://xgfsn44497.execute-api.eu-north-1.amazonaws.com/${stage}/playground-create-api-key`,
            {
              project: project,
            },
            {
                headers: {
                    Accept: '*/*',
                    'Content-Type': 'application/json',
                    'Authorization': `Bearer ${accessToken}`
                },
            });
        return data['api_key'];
    } catch (error) {
        console.error("Error", error);
        throw error;
    }
}